/**
 * The placeholders of text values in `tests.yaml`: `{env:NAME}`, `{today}`, `{today+N}`,
 * `{today-N}` (ISO dates, or in the pattern after a colon: `{today:yyyy}`) and `{base64:…}`,
 * whose content may hold placeholders too.
 */
object LiveTemplates {
    private val TODAY = Regex("""today(?:([+-])(\d+))?(?::(.+))?""")

    fun resolve(template: String): String = parse(template, 0, nested = false).first

    /** [json] with the placeholders of its strings replaced. */
    fun resolveJson(json: String): String = resolveStrings(kotlinx.serialization.json.Json.parseToJsonElement(json)).toString()

    private fun resolveStrings(json: kotlinx.serialization.json.JsonElement): kotlinx.serialization.json.JsonElement = when (json) {
        is kotlinx.serialization.json.JsonObject -> kotlinx.serialization.json.JsonObject(json.mapValues { resolveStrings(it.value) })
        is kotlinx.serialization.json.JsonArray -> kotlinx.serialization.json.JsonArray(json.map(::resolveStrings))
        is kotlinx.serialization.json.JsonPrimitive -> if (json.isString) kotlinx.serialization.json.JsonPrimitive(resolve(json.content)) else json
    }

    private fun parse(text: String, start: Int, nested: Boolean): Pair<String, Int> {
        val out = StringBuilder()
        var index = start
        while (index < text.length) {
            when (val char = text[index]) {
                '{' -> {
                    val (value, next) = placeholder(text, index + 1)
                    out.append(value)
                    index = next
                }
                '}' -> if (nested) return out.toString() to index + 1 else throw IllegalArgumentException("Unbalanced '}' in '$text'")
                else -> {
                    out.append(char)
                    index++
                }
            }
        }
        return out.toString() to index
    }

    private fun placeholder(text: String, start: Int): Pair<String, Int> {
        if (text.startsWith("base64:", start)) {
            val (inner, next) = parse(text, start + "base64:".length, nested = true)
            return Base64.getEncoder().encodeToString(inner.toByteArray()) to next
        }
        val end = text.indexOf('}', start)
        val content = text.substring(start, end)
        val value = when {
            content.startsWith("env:") -> System.getenv(content.removePrefix("env:")) ?: ""
            content.startsWith("today") -> {
                val match = TODAY.matchEntire(content) ?: throw IllegalArgumentException("Malformed placeholder '{$content}'")
                val days = (match.groupValues[2].toLongOrNull() ?: 0).let { if (match.groupValues[1] == "-") -it else it }
                val date = LocalDate.now().plusDays(days)
                match.groupValues[3].takeIf { it.isNotEmpty() }?.let { date.format(DateTimeFormatter.ofPattern(it)) } ?: date.toString()
            }
            else -> throw IllegalArgumentException("Unknown placeholder '{$content}'")
        }
        return value to end + 1
    }
}
